oix","options":[{"id":"a","texte":"Aucun : les deux sont entièrement consommés"},{"id":"b","texte":"Le dihydrogène : il est entièrement consommé"},{"id":"c","texte":"Le dioxygène : il est entièrement consommé"},{"id":"d","texte":"L’eau : elle arrête la réaction"}],"multiple":false},{"enonce":"Touche la case qui indique l’essai où les deux gaz ont été entièrement consommés.","aide":"Cherche la case où il ne reste aucun gaz.","type":"zone","document":"essais","multiple":false}]}$ex$::jsonb,
