   $ex${"titre":"L’orage qui s’approche","competence":"raisonner","situation":"Un soir d’orage, Malo compte les secondes entre l’éclair et le tonnerre, toutes les dix minutes, pour savoir si l’orage s’approche. Il utilise la règle : on divise le nombre de secondes par 3 pour avoir la distance en kilomètres.","documents":[{"id":"orage","type":"tableau","titre":"Les relevés de Malo","colonnes":["Heure","Secondes entre éclair et tonnerre"],"lignes":[["21 h 00",12],["21 h 10",9],["21 h 20",6],["21 h 30",3]],"enteteLignes":true,"source":"Relevés écrits pour l’exercice"}],"questions":[{"enonce":"Touche le relevé où l’orage est le plus proche.","aide":"Moins il y a de secondes, plus l’orage est proche.","type":"zone","document":"orage","multiple":false},{"enonce":"À quelle distance se trouve l’orage à 21 h 20, en kilomètres ?","aide":"Divise le nombre de secondes par 3.","type":"nombre","unite":"km"},{"enonce":"Pourquoi voit-on l’éclair avant d’entendre le tonnerre ?","aide":"Compare les vitesses de la lumière et du son.","type":"choix","options":[{"id":"a","texte":"L’éclair est produit avant le tonnerre dans le nuage"},{"id":"b","texte":"Le son va plus vite que la lumière"},{"id":"c","texte":"La lumière (300 000 km/s) va bien plus vite que le son (340 m/s)"},{"id":"d","texte":"Le son part plus tard que la lumière"}],"multiple":false},{"enonce":"De combien de kilomètres l’orage s’est-il rapproché entre 21 h 00 et 21 h 30 ?","aide":"Calcule la distance à 21 h 00, puis à 21 h 30, et fais la différence.","type":"nombre","unite":"km"},{"enonce":"Il a avancé de 3 km en 30 minutes, à vitesse constante. Dans combien de minutes, après 21 h 30, sera-t-il à la verticale de Malo ?","aide":"Trouve d’abord la distance parcourue en 1 minute, puis combien de minutes il faut pour 1 km.","type":"nombre","unite":"min"}]}$ex$::jsonb,
