e seule espèce.","type":"association","gauche":[{"id":"g0","texte":"Précipité vert avec la soude"},{"id":"g1","texte":"Précipité blanc qui noircit avec le nitrate d’argent"},{"id":"g2","texte":"Sulfate de cuivre anhydre qui devient bleu"},{"id":"g3","texte":"Détonation à l’approche d’une flamme"}],"droite":[{"id":"d0","texte":"Du dihydrogène"},{"id":"d1","texte":"Des ions chlorure"},{"id":"d2","texte":"Des ions fer II"},{"id":"d3","texte":"De l’eau"}]},{"enonce":"Que doit écrire Inès pour le test 2 dans son compte rendu ?","aide":"Ne conclus jamais par une couleur.","type":"choix","options":[{"id":"a","texte":"Le précipité est blanc"},{"id":"b","texte":"La solution est noircie par la lumière"},{"id":"c","texte":"La solution contient des ions chlorure"},{"id":"d","texte":"Le nitrate d’argent est un précipité"}],"multiple":false}]}$ex$::jsonb,
